-- Article 57(1), 59(1), 89 Law 36/2024/QH15. Keep legacy B1 history intact.
UPDATE license_categories SET code='B1_LEGACY', name='B1 ô tô (danh mục trước 2025)', is_active=0 WHERE code='B1' AND (description LIKE '%tự động%' OR name LIKE '%tự động%');
UPDATE courses c JOIN license_categories l ON l.id=c.category_id SET c.is_active=0 WHERE l.code='B1_LEGACY';
UPDATE license_categories SET is_active=0 WHERE code IN ('A2','A3','A4','B2','E','F','FB2','FC','FD','FE');
